const kpiEl = document.getElementById('kpi-arr');
const asOfEl = document.getElementById('as-of');
asOfEl.textContent = String(window.MJVideo.Data['__asOf'] ?? '');
window.MJVideo.OnFrame((timeSeconds) => {
  kpiEl.innerHTML = window.MJChartKit.KpiTile({
    Frame: { Width: 640, Height: 240, StartSeconds: 0, DurationSeconds: 1.5 },
    Value: Number(window.MJVideo.Data['arr_total']),
    Label: 'Annual Recurring Revenue',
    BindingKey: 'arr_total',
    Format: { Kind: 'Currency', Currency: 'USD', Decimals: 1 }
  }, timeSeconds);
});
